/** Static province metadata generated by scripts/build-geo.ts. */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

export interface ProvinceMeta {
  id: string;
  name: string;
  centroid: [number, number];
  neighbours: string[];
}

const file = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../data/provinces.json');
export const PROVINCES: ProvinceMeta[] = JSON.parse(fs.readFileSync(file, 'utf8'));
export const PROVINCE_META = new Map(PROVINCES.map((p) => [p.id, p]));
